arguments.argument:
//Goes to Ballora stage
if pull = 0
and image_index > 10.2
{
    sprite_index = spr_ballorastage
    image_speed = 0.3
    sound_play(snd_music_ballora)
    instance_deactivate_object(obj_camera_button)
    instance_deactivate_object(obj_mask_button)
     instance_deactivate_object(obj_camera)
    instance_deactivate_object(obj_mask)

}
if pull = 1
and image_index < 0
    instance_destroy()
//ballora stage movement
if move = 0
{
    offset -= 1
    if offset < -180
    {
        alarm[0] = 30
        move = 2
    }
}
if move = 1
{
    offset += 1
    if offset > 68
    {
        alarm[1] = 30
        move = 2
    }
}
interruptedimg += 1
if instance_exists(obj_powerout)
and sprite_index = spr_ballorastage
{
    sprite_index = spr_run
    image_index = 10.2
    image_speed = -0.3
    pull = 1
    sound_stop(snd_walk_ballora)
    sound_play(snd_walk_ballora2)
}
